namespace {
constexpr uint32_t kMission = A(0x2A9F98), kDifficulty = A(0x207320), kState = A(0x3B2414), kPaused = A(0x3B2428);
constexpr uint32_t kFade = A(0x2A977C), kLevel = A(0x329480);
constexpr uint32_t kAccelerate = A(0x1E3160), kFriction = A(0x1E3178);

const char* const kMissionNames[12] = {"Trouble in Paradise", "Precious Cargo", "Dangerous Pursuit", "Bad Diplomacy",
                                       "Cold Reception", "Night of the Jackal", "Streets of Bucharest", "Fire & Water",
                                       "Forbidden Depths", "Poseidon", "Mediterranean Crisis", "Evil Summit"};
const char* const kDifficulties[3] = {"Operative", "Agent", "00 Agent"};

bool InFrontend() {
    const uint32_t state = kernel::R32(kState), name = state ? kernel::R32(state + 0x10) : 0;
    return !state || (name && !std::strncmp(reinterpret_cast<const char*>(&kernel::G<uint8_t>(name)), "frontend", 8));
}

bool KeyDown(uint32_t choice) {
#ifdef _WIN32
    const int vk = auf::KeyOf(choice);
    return vk && (GetAsyncKeyState(vk) & 0x8000) && GetForegroundWindow() == static_cast<HWND>(app::Window()) &&
           !app::OverlayOpen();
#else
    (void)choice;
    return false;
#endif
}

void Presence() {
    static std::string said;
    static int64_t since = 0;
    std::string details, state;
    if (InFrontend()) details = "In the menus";
    else {
        const uint32_t m = kernel::R32(kMission), d = kernel::R32(kDifficulty);
        details = std::string("Playing ") + (m < 12 ? kMissionNames[m] : "a mission");
        state = d < 3 ? kDifficulties[d] : "";
        if (kernel::R32(kPaused)) state += state.empty() ? "Paused" : ", paused";
    }
    const std::string key = details + "\n" + state;
    if (key == said) return;
    if (said.substr(0, said.find('\n')) != details) since = int64_t(std::time(nullptr));  // a new mission: its own time
    said = key;
    app::SetPresence(details, state, since);
}

void RestartKey(X86Context& ctx, uint8_t* base) {
    static bool was = false;
    const bool down = KeyDown(auf::restart_key);
    if (down && !was && (InFrontend() || kernel::R32(kPaused) || kernel::R32(kFade) != 0))
        LOGR("auf: the restart key refused: menus %d, paused %u, fade %u", InFrontend(), kernel::R32(kPaused), kernel::R32(kFade));
    if (down && !was && !InFrontend() && !kernel::R32(kPaused) && kernel::R32(kFade) == 0) {
        LOGR("auf: the restart key: the mission again");
        X86_PUSH32(0x15DDF0u);  // no arguments: the return address only
        sub_00033510(ctx, base);
    }
    was = down;
}

// ---- weapon keys
uint32_t GuestCall(X86Context& ctx, uint32_t ecx, uint32_t fn, std::initializer_list<uint32_t> args) {
    const uint32_t saved = ctx.ecx;
    ctx.ecx = ecx;
    const uint32_t r = kernel::CallGuest(ctx, fn, args);
    ctx.ecx = saved;
    return r;
}

// the weapons the cycle would offer, in its order
int Weapons(X86Context& ctx, uint32_t player, uint32_t* out, int most) {
    const uint32_t vt = kernel::R32(player), count = std::min<uint32_t>(kernel::R32(player + 0x318), 64);
    uint32_t item = GuestCall(ctx, player, kernel::R32(vt + 0x9C), {0, 0, 0});
    int n = 0;
    const uint32_t first = item;
    for (uint32_t i = 0; i < count && item && n < most; i++) {
        if (!kernel::G<uint8_t>(item + 0x395) && (GuestCall(ctx, player, A(0xAF770), {item}) & 0xFF)) out[n++] = item;
        item = GuestCall(ctx, player, kernel::R32(vt + 0xC0), {item, 0});
        if (item == first) break;
    }
    return n;
}

// Headless or without a desktop: AUF_KEY_TEST=frame:key,... holds that key (a vk, or a digit or letter) for 8 weapon frames from
// the frame on (a frame is a call of the player's think)
bool Injected(int vk, uint32_t frame) {
    static const char* e = std::getenv("AUF_KEY_TEST");
    for (const char* p = e; p && *p;) {
        char* end;
        const unsigned long at = std::strtoul(p, &end, 10);
        if (*end != ':') break;
        if (end[1] == vk && frame >= at && frame < at + 8) return true;
        p = std::strchr(end, ',');
        if (p) p++;
    }
    return false;
}
uint32_t g_frame = 0;

bool Held(int vk) {
    if (Injected(vk, g_frame)) return true;
#ifdef _WIN32
    return vk && (GetAsyncKeyState(vk) & 0x8000) && GetForegroundWindow() == static_cast<HWND>(app::Window()) && !app::OverlayOpen();
#else
    (void)vk;
    return false;
#endif
}

void WeaponKeys(X86Context& ctx, uint32_t player) {
    g_frame++;
    static uint32_t current = 0, previous = 0;
    static bool was[10] = {};
    static uint32_t check_at = 0, check_for = 0;
    if (check_at && g_frame >= check_at) {
        LOGR("auf: weapon in hand %08X after the key (wanted %08X)", kernel::R32(player + 0x2EC), check_for);
        check_at = 0;
    }
    const uint32_t now = kernel::R32(player + 0x2EC);
    if (now && now != current) {
        if (current) previous = current;
        current = now;
    }
    if (!InFrontend() && kernel::R32(kPaused) == 0 && !auf::MenuUp() && input::UsingKeyboard() &&
        kernel::R32(player + 0x1C0) == 0 && kernel::R32(player + 0x2F0) == 0 && now && kernel::R32(now + 0x3D4) == 0) {
        int want = -1;  // a weapon's place, or 9 for the previous one
        bool down[10];
        for (int k = 0; k < 9; k++) down[k] = auf::weapon_keys && Held('1' + k);
        down[9] = Held(auf::LetterKeyOf(auf::previous_weapon_key));
        for (int k = 0; k < 10; k++)
            if (down[k] && !was[k] && want < 0) want = k;
        std::copy(down, down + 10, was);
        if (want >= 0) {
            uint32_t list[16];
            const int n = Weapons(ctx, player, list, 16);
            uint32_t pick = 0;
            if (want == 9) {
                for (int i = 0; i < n; i++)
                    if (list[i] == previous) pick = previous;
            } else if (want < n) pick = list[want];
            LOGR("auf: weapon key %d: %d weapons, picks %08X (now %08X, previous %08X)", want + 1, n, pick, now, previous);
            if (pick && pick != now) {
                check_at = g_frame + 90, check_for = pick;
                kernel::G<uint32_t>(player + 0x444) = pick;
                kernel::G<uint32_t>(player + 0x440) = pick;
                kernel::G<uint32_t>(player + 0x458) = kernel::R32(A(0x329490));
            }
        }
    } else {
        std::fill(std::begin(was), std::end(was), true);  // a key held through a menu is not a press
        for (int k = 0; k < 9; k++) was[k] = Held('1' + k);
        was[9] = Held(auf::LetterKeyOf(auf::previous_weapon_key));
    }
}
}  // namespace

namespace auf {
// once a frame (the full screen 2D pass's hook, src/bond/hooks.cpp)
void BondFrame(X86Context& ctx, uint8_t* base) {
    Presence();
    RestartKey(ctx, base);
    settings_page::Watch();  // a binding left waiting when its page went away
}
}  // namespace auf

// a cinematic's skip, pressed once as it starts
// the press once a cinematic's skip thread is set (the world's +0x20C, [0x33BCC4]): pressed at the very start, before
// the script names it, the press is spent on nothing; a restarted level (its time [0x329490] going back) is a new one
X86_EXTERN_FUNC(__imp__sub_000BD910);
X86_FUNC(sub_000BD910) {
    static bool pressed = false;
    static float last_time = 0;
    float now;
    std::memcpy(&now, &kernel::G<uint32_t>(A(0x329490)), 4);
    if (now < last_time) pressed = false;
    last_time = now;
    const bool cinematic = kernel::R32(kLevel + 0x180) != 0;
    const uint32_t world = kernel::R32(A(0x33BCC4));
    const bool skippable = world && kernel::R32(world + 0x20C) != 0;
    if (!cinematic) pressed = false;
    else if (auf::skip_cutscenes && skippable && !pressed && ctx.ecx) {
        pressed = true;
        kernel::G<uint32_t>(ctx.ecx + 0x4D0) |= 0x1;
        LOGR("auf: a cutscene skipped (skip_cutscenes)");
    }
    const uint32_t me = ctx.ecx;
    if (me && !cinematic && kernel::R32(A(0x329390)) && me == kernel::R32(kernel::R32(A(0x329390)) + 0x278)) WeaponKeys(ctx, me);
    ctx.ecx = me;
    __imp__sub_000BD910(ctx, base);
}

// player movement: sharper with the keyboard
X86_EXTERN_FUNC(__imp__sub_000C7310);
X86_FUNC(sub_000C7310) {
    const bool tight = auf::tight_movement && input::UsingKeyboard() && !auf::MenuUp();
    float accelerate = 0, friction = 0;
    if (tight) {
        std::memcpy(&accelerate, &kernel::G<uint32_t>(kAccelerate), 4);
        std::memcpy(&friction, &kernel::G<uint32_t>(kFriction), 4);
        const float a = accelerate * 2.5f, f = friction * 1.7f;
        std::memcpy(&kernel::G<uint32_t>(kAccelerate), &a, 4);
        std::memcpy(&kernel::G<uint32_t>(kFriction), &f, 4);
    }
    __imp__sub_000C7310(ctx, base);
    if (tight) {
        std::memcpy(&kernel::G<uint32_t>(kAccelerate), &accelerate, 4);
        std::memcpy(&kernel::G<uint32_t>(kFriction), &friction, 4);
    }
    // AUF_MOVE_TRACE=1: player 1's speed along the ground (its entity's +0x88) while it changes, to compare starts and
    // stops (driven by AUF_PAD's left_stick_up*secs)
    static const bool trace = std::getenv("AUF_MOVE_TRACE") != nullptr;
    const uint32_t g = trace ? kernel::R32(A(0x329390)) : 0, me = g ? kernel::R32(g + 0x278) : 0;
    if (me) {
        float v[2], t;
        std::memcpy(v, &kernel::G<uint32_t>(me + 0x88), 8);
        std::memcpy(&t, &kernel::G<uint32_t>(A(0x329490)), 4);
        static float last = 0;
        const float speed = std::sqrt(v[0] * v[0] + v[1] * v[1]);
        if (std::abs(speed - last) > 0.5f) LOGR("move: %.3f s speed %.1f%s", t, speed, tight ? " (tight)" : "");
        last = speed;
    }
}
